import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // 静态导出：只有 out/ 才能在客户端里直接预览，不引 dev server（设计 §4.6）
  output: "export",
  // 预览走 lumii-local://local/<abs>/out/index.html，根绝对路径 /_next 会解析到
  // 协议根而 404，必须用相对前缀
  assetPrefix: ".",
  images: { unoptimized: true },
  reactCompiler: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
